<a href="<?= e(route_url('/community')) ?>" class="text-link small muted" style="margin-bottom:22px"><?= icon('arrow-left',15) ?> Back to my learning circle</a><div class="page-header"><div><span class="eyebrow">FEEDBACK THAT HELPS SOMEONE GROW</span><h1>A fresh perspective.</h1><p>Be specific, constructive and kind. Review the shared snapshot, not the person.</p></div><?= badge($review['status']) ?></div><div class="two-column"><section class="card form-card"><h2 style="font-size:23px;margin-bottom:17px"><?= e($review['snapshot_title']) ?></h2><div class="prose" style="white-space:pre-wrap"><?= e($review['snapshot_description']) ?></div><div class="page-actions" style="margin-top:25px"><?php if($review['snapshot_url']): ?><a class="btn btn-secondary btn-small" href="<?= e($review['snapshot_url']) ?>" target="_blank" rel="noopener noreferrer">Open project <?= icon('arrow-up-right',14) ?></a><?php endif; ?><?php if($review['snapshot_repository']): ?><a class="btn btn-secondary btn-small" href="<?= e($review['snapshot_repository']) ?>" target="_blank" rel="noopener noreferrer">View source <?= icon('code',14) ?></a><?php endif; ?></div><div class="notice info" style="margin-top:25px"><?= icon('lock',17) ?><p>This snapshot was shared only with assigned reviewers. Don’t redistribute private work. Feedback does not award approval, XP or a certificate.</p></div><p class="fine-print">Project owner ID: #<?= (int)$review['user_id'] ?> · Review deadline: <?= niceDate($review['due_at'],'M j, Y · H:i') ?> UTC. Report concerns from Community.</p></section><section class="card form-card"><h2 class="form-section-title">Help the next version get better.</h2><p class="form-section-description">Score each criterion and explain one useful observation or next step.</p><?php if($review['status']==='assigned'): ?><form action="<?= e(route_url('/api/reviews/' . ((int)$review['id']))) ?>" method="post" data-api data-confirm="Submit your constructive feedback? Submitted reviews cannot be edited."><?= csrfField() ?><?php foreach($questions as $q): ?><div class="review-prompt"><h3><?= e($q['prompt']) ?></h3><div class="rating-options"><?php for($i=1;$i<=$q['max_score'];$i++): ?><label class="rating-option"><input type="radio" name="responses[<?= (int)$q['id'] ?>][score]" value="<?= $i ?>" required><span><?= $i ?></span></label><?php endfor; ?></div><div class="field"><label for="feedback-<?= (int)$q['id'] ?>">Constructive feedback</label><textarea id="feedback-<?= (int)$q['id'] ?>" name="responses[<?= (int)$q['id'] ?>][feedback]" required minlength="10" maxlength="3000" placeholder="I noticed… One thing to try next is…"></textarea></div></div><?php endforeach; ?><button class="btn btn-primary btn-block">Share a thoughtful review <?= icon('message',16) ?></button></form><?php else: ?><?php foreach($responses as $r): ?><div class="review-prompt"><h3><?= e($r['prompt']) ?> · <?= (int)$r['score'] ?>/<?= (int)$r['max_score'] ?></h3><p style="font-size:12px;line-height:1.9;color:var(--muted);white-space:pre-wrap"><?= e($r['feedback']) ?></p></div><?php endforeach; ?><p class="notice success"><?= icon('check-circle',18) ?> Your perspective is shared. Thank you for helping someone grow.</p><?php endif; ?></section></div>
